private fun buildVectorIcon(name: String, pathDataStr: String): ImageVector {
    val nodes = PathParser().parsePathString(pathDataStr).toNodes()
    return ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    ).addPath(
        pathData = nodes,
        fill = SolidColor(Color.White),
    ).build()
}

